		/** 
		 * Tests creating a new Offer.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Offer");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Offer" );

			try {            
				Offer entity = OfferService.getOfferInstance().createOffer( generateNewEntity() );
				thePrimaryKey = entity.getOfferId();
				LOGGER.info( "-- Successfully created a Offer with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Offer. 
		 */
		public Offer testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Offer" );

			Offer entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Offer with primary key" );
			msg.append( thePrimaryKey );
			
			OfferFetchOneSummary fetchOneSummary = new OfferFetchOneSummary( thePrimaryKey );

			try {
				entity = OfferService.getOfferInstance().getOffer( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Offer " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Offer.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Offer." );

			StringBuilder msg = new StringBuilder( "Failed to update a Offer : " );        
			Offer entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Offer." );

				// for use later on...
				thePrimaryKey = entity.getOfferId();

				OfferService proxy = OfferService.getOfferInstance();            
				proxy.updateOffer( entity );   

				LOGGER.info( "-- Successfully saved Offer - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Offer.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Offer." );

			try{
			    Offer entity = testRead(); 
				OfferService.getOfferInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Offer with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Offer with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Offers.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Offers:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Offer : " );        
			List<Offer> collection  = null;

			try {
				// call the static get method on the OfferService
				collection = OfferService.getOfferInstance().getAllOffer();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Offer entity = null;            
					Iterator<Offer> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getOfferId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

